Use the `pg` library's `Pool` class — here's a production-ready setup:

```javascript
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // Pool sizing
  max: 20,                    // max connections (default: 10)
  min: 2,                     // keep alive minimum connections
  // Timeouts (all in milliseconds)
  connectionTimeoutMillis: 5000,   // fail fast if no connection available
  idleTimeoutMillis: 30000,        // release idle connections after 30s
  query_timeout: 10000,            // per-query timeout
  statement_timeout: 10000,        // postgres-side statement timeout
  // SSL (for production/cloud DBs)
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: true } : false,
});

// Catch pool-level errors (e.g. dropped connections) — without this,
// uncaught errors crash the process
pool.on('error', (err) => {
  console.error('Unexpected pool error', err);
});
```

**For individual queries:**

```javascript
async function query(text, params) {
  const start = Date.now();
  try {
    const result = await pool.query(text, params);
    return result;
  } catch (err) {
    // pg error codes: https://www.postgresql.org/docs/current/errcodes-appendix.html
    if (err.code === '57014') throw new Error('Query timed out');
    if (err.code === '08006') throw new Error('DB connection lost');
    throw err;
  } finally {
    // optional: log slow queries
    const duration = Date.now() - start;
    if (duration > 1000) console.warn('Slow query', { text, duration });
  }
}
```

**For transactions (must use a dedicated client):**

```javascript
async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // always release back to pool
  }
}

// Usage:
await withTransaction(async (client) => {
  await client.query('INSERT INTO orders ...', [...]);
  await client.query('UPDATE inventory ...', [...]);
});
```

**Key things to get right:**

- `pool.on('error')` is mandatory — without it, idle client errors are unhandled exceptions
- Always `release()` in a `finally` block or you'll exhaust the pool
- `connectionTimeoutMillis` is what you actually want for "slow DB" detection; `idleTimeoutMillis` is about reclaiming unused connections
- For serverless (Lambda, Vercel), use `pg-pool` with `max: 1` or switch to `@neondatabase/serverless` / `postgres` (the `postgres` npm package handles serverless better than `pg`)
